  Player.prototype.update = function (dt) {
    this._now += dt;
    if (!this.enabled) { this.target = null; return; }

    this._updateWaterState();
    var wish = this._wishDir();

    if (this.fly) {
      var fs = this.sprint ? FLY_SPRINT : FLY;
      var vy = (this.keys.Space ? fs : (this.keys.ShiftLeft || this.keys.ShiftRight ? -fs : 0));
      this._smoothVel(wish.x * fs, wish.z * fs, vy, dt, 10);
    } else if (this.inWater) {
      var spd = (this.sprint ? SPRINT : WALK) * 0.5;
      var targetVy = this.keys.Space ? 3.6 : -2.2;   // 浮力：按住空格上浮，否则缓沉
      this.vel.y += (targetVy - this.vel.y) * Math.min(1, dt * 6);
      this._smoothVel(wish.x * spd, wish.z * spd, this.vel.y, dt, 6);
    } else {
      var spd2 = (this.keys.ShiftLeft || this.keys.ShiftRight) ? SNEAK : (this.sprint ? SPRINT : WALK);
      if (this.keys.Space && this.onGround) this.vel.y = JUMP_V;
      this.vel.y -= GRAVITY * dt;
      if (this.vel.y < -60) this.vel.y = -60;
      this._smoothVel(wish.x * spd2, wish.z * spd2, this.vel.y, dt, this.onGround ? 14 : 4);
    }

    // 分轴移动 + 碰撞
    this.onGround = false;
    this._moveAxis(1, this.vel.y * dt);
    this._moveAxis(0, this.vel.x * dt);
    this._moveAxis(2, this.vel.z * dt);

    // 掉出世界 → 回出生点
    if (this.pos.y < -10) this.respawn();

    // 相机跟随（眼高）
    this.camera.position.set(this.pos.x, this.pos.y + EYE, this.pos.z);
    this.camera.quaternion.setFromEuler(_euler.set(this.pitch, this.yaw, 0, 'YXZ'));

    // 射线与连续挖掘/放置
    this.target = this.raycast();
    if (this._mineHeld) {
      this._mineTimer -= dt;
      if (this._mineTimer <= 0) { this.tryBreak(); this._mineTimer = ACT_INTERVAL; }
    }
    if (this._placeHeld) {
      this._placeTimer -= dt;
      if (this._placeTimer <= 0) { this.tryPlace(); this._placeTimer = ACT_INTERVAL; }
    }
  };
